SELECT multiIf(startsWith(log_comment,'reader-cache-'),'hot-cold experiment',startsWith(log_comment,'reader-qccoff-'),'cold condition-cache-off experiment','other queries') AS activity,count() AS completed_queries,sum(query_duration_ms)/1000 AS summed_elapsed_s,sum(ProfileEvents['UserTimeMicroseconds']+ProfileEvents['SystemTimeMicroseconds'])/1000000 AS summed_cpu_s,max(peak_threads_usage) AS peak_threads FROM clusterAllReplicas(default,merge('system','^query_log')) WHERE event_date BETWEEN toDate('2026-10-11 10:39:14') AND toDate('2026-10-11 10:56:17') AND event_time BETWEEN toDateTime('2026-10-11 10:39:14','UTC') AND toDateTime('2026-10-11 10:56:17','UTC') AND is_initial_query=1 AND type='QueryFinish' GROUP BY activity ORDER BY activity LIMIT 20 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,skip_unavailable_shards=0 FORMAT CSVWithNames
